protected TaxItemGroup getTaxItemGroup()
{
    TaxItemGroup ret = next getTaxItemGroup();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && 
        this.rebatePosting.RebatePaymentType == TAMRebatePaymentType::Fund &&
        this.rebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        return this.rebatePosting.TaxItemGroupFund;
    }

    return ret;
}
